SET NAMES utf8mb4;
-- Clean, credential-free bootstrap. Never import over an existing database.
-- Historical tables/files remain untouched; active catalog uses market_* exclusively.
CREATE TABLE users (
 id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
 username VARCHAR(50) NOT NULL UNIQUE,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,
 full_name VARCHAR(150) NOT NULL DEFAULT '',zip VARCHAR(10) NOT NULL DEFAULT '',city VARCHAR(100) NOT NULL DEFAULT '',
 is_admin TINYINT(1) NOT NULL DEFAULT 0,is_verified TINYINT(1) NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,
 verification_status VARCHAR(16) NOT NULL DEFAULT 'none',auth_version INT NOT NULL DEFAULT 0,
 mfa_secret TEXT NULL,mfa_last_counter BIGINT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE system_settings(setting_key VARCHAR(100) PRIMARY KEY,setting_value TEXT NOT NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE admin_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id INT NULL,action_type VARCHAR(100) NOT NULL,target_id INT NULL,details TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY admin_log_date(created_at),FOREIGN KEY(admin_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE market_categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,parent_id INT UNSIGNED NULL,name VARCHAR(100) NOT NULL,slug VARCHAR(100) NOT NULL UNIQUE,is_active TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(parent_id) REFERENCES market_categories(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE market_listings(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,seller_id INT NOT NULL,category_id INT UNSIGNED NOT NULL,
 title VARCHAR(150) NOT NULL,description TEXT NOT NULL,type VARCHAR(16) NOT NULL,price_cents BIGINT UNSIGNED NOT NULL,
 current_bid_cents BIGINT UNSIGNED NULL,buyout_cents BIGINT UNSIGNED NULL,highest_bidder_id INT NULL,
 status VARCHAR(16) NOT NULL DEFAULT 'draft',ends_at DATETIME NULL,zip VARCHAR(10) NOT NULL,city VARCHAR(100) NOT NULL,
 bumped_at DATETIME NULL,pickup TINYINT(1) NOT NULL DEFAULT 1,shipping TINYINT(1) NOT NULL DEFAULT 0,condition_label VARCHAR(30) NOT NULL DEFAULT 'used',
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY(seller_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(category_id) REFERENCES market_categories(id) ON DELETE RESTRICT,FOREIGN KEY(highest_bidder_id) REFERENCES users(id) ON DELETE RESTRICT,
 KEY browse(status,category_id,created_at),KEY due_auctions(type,status,ends_at),KEY seller(seller_id,status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE market_proxy_bids(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT UNSIGNED NOT NULL,user_id INT NOT NULL,max_cents BIGINT UNSIGNED NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE KEY proxy_user(listing_id,user_id),KEY proxy_priority(listing_id,max_cents,id),FOREIGN KEY(listing_id) REFERENCES market_listings(id) ON DELETE RESTRICT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE market_bids(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT UNSIGNED NOT NULL,user_id INT NULL,amount_cents BIGINT UNSIGNED NULL,event_type VARCHAR(20) NOT NULL,idempotency_key VARCHAR(100) NULL UNIQUE,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),KEY bid_history(listing_id,id),FOREIGN KEY(listing_id) REFERENCES market_listings(id) ON DELETE RESTRICT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE market_images(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT UNSIGNED NOT NULL,storage_key VARCHAR(64) NOT NULL UNIQUE,position INT NOT NULL,width INT NOT NULL,height INT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY image_position(listing_id,position),FOREIGN KEY(listing_id) REFERENCES market_listings(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE market_watchlist(user_id INT NOT NULL,listing_id BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,listing_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(listing_id) REFERENCES market_listings(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE market_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT UNSIGNED NOT NULL,sender_id INT NOT NULL,receiver_id INT NOT NULL,message_text TEXT NOT NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY inbox(receiver_id,is_read,id),KEY conversation(listing_id,sender_id,receiver_id,id),FOREIGN KEY(listing_id) REFERENCES market_listings(id) ON DELETE RESTRICT,FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(receiver_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE market_ratings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT UNSIGNED NOT NULL,sender_id INT NOT NULL,receiver_id INT NOT NULL,stars TINYINT UNSIGNED NOT NULL,comment TEXT NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY rating_once(listing_id,sender_id),CONSTRAINT rating_stars CHECK(stars BETWEEN 1 AND 5),FOREIGN KEY(listing_id) REFERENCES market_listings(id) ON DELETE RESTRICT,FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(receiver_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE market_invoices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,invoice_number VARCHAR(64) NULL UNIQUE,service_code VARCHAR(64) NOT NULL,fee_version VARCHAR(32) NOT NULL,gross_cents BIGINT UNSIGNED NOT NULL,currency VARCHAR(3) NOT NULL DEFAULT 'EUR',status VARCHAR(20) NOT NULL DEFAULT 'draft',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE market_payment_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,provider VARCHAR(32) NOT NULL,status VARCHAR(20) NOT NULL,provider_order_id VARCHAR(128) NULL UNIQUE,capture_id VARCHAR(128) NULL UNIQUE,idempotency_key VARCHAR(64) NOT NULL UNIQUE,mode VARCHAR(16) NOT NULL DEFAULT 'sandbox',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(invoice_id) REFERENCES market_invoices(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE market_payment_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,attempt_id BIGINT UNSIGNED NOT NULL,provider_event_id VARCHAR(128) NOT NULL UNIQUE,kind VARCHAR(64) NOT NULL,payload_hash VARCHAR(64) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(attempt_id) REFERENCES market_payment_attempts(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO market_categories(name,slug,sort_order) VALUES ('Outdoor & Camping','outdoor-camping',10),('Wohnen & Garten','wohnen-garten',20),('Elektronik','elektronik',30),('Mode & Accessoires','mode',40),('Sport & Freizeit','sport-freizeit',50),('Optik & Ferngläser','optik',60),('Werkzeuge','werkzeuge',70),('Bücher & Medien','buecher-medien',80),('Musik & Kreativität','musik',90),('Sammlerzubehör','sammlerzubehoer',100),('Sonstiges','sonstiges',110);

-- Additive; ops/migrate.php handles the optional bumped_at column.
CREATE TABLE IF NOT EXISTS market_manual_orders (
 invoice_id BIGINT UNSIGNED PRIMARY KEY,user_id INT NOT NULL,listing_id BIGINT UNSIGNED NOT NULL,
 reference VARCHAR(64) NOT NULL UNIQUE,recipient VARCHAR(190) NOT NULL,quantity INT NOT NULL,
 net_cents BIGINT UNSIGNED NOT NULL,tax_cents BIGINT UNSIGNED NOT NULL,tax_bps INT NOT NULL,
 terms_hash VARCHAR(64) NOT NULL,terms_text TEXT NOT NULL,request_key VARCHAR(64) NOT NULL UNIQUE,
 customer_claimed_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(invoice_id) REFERENCES market_invoices(id) ON DELETE RESTRICT,
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,
 FOREIGN KEY(listing_id) REFERENCES market_listings(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS market_bump_credits (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL UNIQUE,user_id INT NOT NULL,
 quantity INT NOT NULL,remaining INT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(invoice_id) REFERENCES market_invoices(id) ON DELETE RESTRICT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS market_bump_events (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,credit_id BIGINT UNSIGNED NOT NULL,listing_id BIGINT UNSIGNED NOT NULL,user_id INT NOT NULL,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(credit_id) REFERENCES market_bump_credits(id) ON DELETE RESTRICT,FOREIGN KEY(listing_id) REFERENCES market_listings(id) ON DELETE RESTRICT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,
 KEY bump_history(listing_id,created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
